CREATE TABLE rv_auth_refresh (id BINARY(16) PRIMARY KEY, family_id BINARY(16) NOT NULL, token_hash BINARY(32) NOT NULL UNIQUE, issued_at DATETIME(6) NOT NULL, expires_at DATETIME(6) NOT NULL, consumed_at DATETIME(6), replaced_by BINARY(16), revoked_at DATETIME(6), CONSTRAINT fk_auth_refresh_family FOREIGN KEY ix_auth_refresh_family (family_id) REFERENCES rv_auth_refresh_family(id) ON DELETE CASCADE);
